 94	    /**
 95	     * Controls the functionality of the Play/Pause button. This depends
 96	     * on whether the simulation is paused or not.
 97	     */
 98	    private void handlePlayPause() 
 99	    {
100	        boolean isPaused = time.getIsPaused();
101	        
102	        time.toggleIsPaused();
103	        
104	        if (isPaused) {
105	            if (! time.getIsFinished()) {
106	                simulate();
107	            }
108	        }
109	        
110	        updateButtonState();
111	    }
