134	    /**
135	     * Run the simulation from its current state for the given number of 
136	     * steps in the Time Class.
137	     * Stop before the given number of steps if it ceases to be viable.
138	     * This is considered to be when only one species remains.
139	     */
140	    private void simulate() 
141	    {
142	        time.setIsPaused(false);
143	        
144	        // Adjust button visibility.
145	        updateButtonState();
146	        
147	        while (! time.getIsPaused() && ! time.getIsFinished() && view.isViable(field)) {
148	            simulateOneStep();
149	        }
150	        
151	        time.setIsPaused(true);
152	        updateButtonState();
153	    }
