155	    /**
156	     * Run the simulation from its current state for a single step.
157	     * Iterate over the whole field updating the state of each
158	     * predator, prey, and plant.
159	     */
160	    private void simulateOneStep()
161	    {
162	        time.incrementStep();
163	        weather.updateWeather();
164	
165	        // Provide space for newborn animals and plants;
166	        List<LivingOrganism> newAnimals = new ArrayList<>();
167	        List<LivingOrganism> newPlants = new ArrayList<>();
168	
169	        advanceOrganisms(animals, newAnimals);
170	        advanceOrganisms(plants, newPlants);
171	        
172	        // Add the newly born animals and plants to the main lists.
173	        animals.addAll(newAnimals);
174	        plants.addAll(newPlants); 
175	
176	        // Show the current state in the view.
177	        view.showStatus(field);
178	    }
