180	    /**
181	     * Reset the simulation to a starting position.
182	     */
183	    private void reset()
184	    {
185	        // Resets the visibility of the buttons and resets the step number
186	        time.resetStep();
187	        updateButtonState();
188	        
189	        // Clears all current animals and plants then repopulates the area
190	        animals.clear();
191	        plants.clear();
192	        populate();
193	        
194	        // Show the starting state in the view.
195	        view.showStatus(field);
196	    }
