276	    private void advanceOrganisms(List<LivingOrganism> organisms, List<LivingOrganism> newbornOrganisms)
277	    {
278	        for(Iterator<LivingOrganism> it = organisms.iterator(); it.hasNext(); ) 
279	        {
280	            LivingOrganism organism = it.next();
281	            
282	            if(organism != null) 
283	            {
284	                organism.act(newbornOrganisms);
285	                
286	                if (! organism.isAlive())
287	                {
288	                    it.remove();
289	                }
290	            }
291	        }
292	    }
