 65	    /**
 66	     * Controls the functionality of the Play/Pause button. This depends
 67	     * on whether the simulation is paused or not.
 68	     */
 69	    private void handlePlayPause() 
 70	    {
 71	        boolean isPaused = time.getIsPaused();
 72	        
 73	        time.toggleIsPaused();
 74	        
 75	        if (isPaused) {
 76	            if (! time.getIsFinished()) {
 77	                simulate();
 78	            }
 79	        }
 80	        
 81	        updateButtonState();
 82	    }
