 93	    /**
 94	     * Run the simulation from its current state for the given number of 
 95	     * steps.
 96	     * @param numSteps The number of steps to run for.
 97	     */
 98	    private void simulate(int numSteps)
 99	    {
100	        // Sets the number of steps that the simulation run started at
101	        time.setStepsToRunFor(numSteps);
102	        simulate();
103	    }
