105	    /**
106	     * Run the simulation from its current state for the given number of 
107	     * steps in the Time Class.
108	     * Stop before the given number of steps if it ceases to be viable.
109	     * This is considered to be when only one species remains.
110	     */
111	    private void simulate() 
112	    {
113	        time.setIsPaused(false);
114	        
115	        // Adjust button visibility.
116	        updateButtonState();
117	        
118	        while (! time.getIsPaused() && ! time.getIsFinished() && view.isViable(field)) {
119	            simulateOneStep();
120	        }
121	        
122	        time.setIsPaused(true);
123	        updateButtonState();
124	    }
