126	    /**
127	     * Run the simulation from its current state for a single step.
128	     * Iterate over the whole field updating the state of each
129	     * predator, prey, and plant.
130	     */
131	    private void simulateOneStep()
132	    {
133	        time.incrementStep();
134	        weather.updateWeather();
135	
136	        // Provide space for newborn animals and plants;
137	        List<LivingOrganism> newAnimals = new ArrayList<>();
138	        List<LivingOrganism> newPlants = new ArrayList<>();
139	
140	        advanceOrganisms(animals, newAnimals);
141	        advanceOrganisms(plants, newPlants);
142	        
143	        // Add the newly born animals and plants to the main lists.
144	        animals.addAll(newAnimals);
145	        plants.addAll(newPlants); 
146	
147	        // Show the current state in the view.
148	        view.showStatus(field);
149	    }
