152	     * Reset the simulation to a starting position.
153	     */
154	    private void reset()
155	    {
156	        // Resets the visibility of the buttons and resets the step number
157	        time.resetStep();
158	        updateButtonState();
159	        
160	        // Clears all current animals and plants then repopulates the area
161	        animals.clear();
162	        plants.clear();
163	        simulationFactory.populate(field, animals, plants);
164	        
165	        // Show the starting state in the view.
166	        view.showStatus(field);
167	    }
