195	    /**
196	     * Let a collection of organisms act and remove any that die this step.
197	     */
198	    private void advanceOrganisms(List<LivingOrganism> organisms, List<LivingOrganism> newbornOrganisms)
199	    {
200	        for(Iterator<LivingOrganism> it = organisms.iterator(); it.hasNext(); ) 
201	        {
202	            LivingOrganism organism = it.next();
203	            
204	            if(organism != null) 
205	            {
206	                organism.act(newbornOrganisms);
207	                
208	                if (! organism.isAlive())
209	                {
210	                    it.remove();
211	                }
212	            }
213	        }
214	    }
