218	     */
219	    private void updateButtonState() 
220	    {
221	        boolean isFinished = time.getIsFinished();
222	        boolean isStopped = time.getIsPaused() || isFinished;
223	
224	        // Adjust button usability.
225	        playPauseButton.setEnabled(!isFinished);
226	        runLongSimulationButton.setEnabled(isStopped);
227	        simulateOneStepButton.setEnabled(isStopped);
228	        resetButton.setEnabled(isStopped);
229	        
230	        // Set the label on the play/pause button.
231	        playPauseButton.setText(isStopped ? PLAY_LABEL : PAUSE_LABEL);
232	    }
